head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gLdMktTpCd = js_market; // 로그인사용자의 시장구분
scwin.gSndlocTp = $c.frame.path("../frame_head").gSndlocTpCd;
scwin.gAcptNo = $c.frame.path("../frame_head").scwin.gAcptNo;
scwin.gProcsStatCd = $c.frame.path("../frame_head").scwin.gProcsStatCd;
scwin.gDepCd = js_dep_cd;
scwin.gBelngDepCd = js_belngdepcd;
scwin.gDutyGrp = js_gduty;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 	
scwin.gEmpNo = js_emp_no; // 세션정보 	
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gNxtTpCd = $c.frame.path("../frame_head").scwin.gNxtTpCd; // 익일당일여부
scwin.gDoc_LdMktTp = $c.frame.path("../frame_head").scwin.gDoc_LdMktTp;
scwin.gLangTpCd = $c.frame.path("../frame_head").scwin.gLangTpCd; // 국문:0, 영문=1	
scwin.gDisclsAcptTpCd = $c.frame.path("../frame_head").scwin.gDisclsAcptTpCd; // A=첨부추가, M= 정정, U =첨부정정, F=최초
scwin.gSubmitSysTp = $c.frame.path("../frame_head").scwin.gSubmitSysTp; // 제출구문 - 한글자동변환 :0=국문제출, 1=영문제출

//연계공시개발
scwin.gHdcomLnkDisclsYn = $c.frame.path("../frame_head").scwin.gHdcomLnkDisclsYn;
scwin.gSubcomDisclsProcsStatCd = $c.frame.path("../frame_head").scwin.gSubcomDisclsProcsStatCd;
scwin.gSubcomNxtddTddTpCd = $c.frame.path("../frame_head").scwin.gSubcomNxtddTddTpCd;
//연계공시개발

scwin.gTrdHaltMsg = $c.frame.path("../frame_head").scwin.gTrdHaltMsg;
scwin.gFormWarnContn = $c.frame.path("../frame_head").scwin.gFormWarnContn; //공동공시 유의사항
scwin.gAtsIsuYn = $c.frame.path("../frame_head").scwin.gAtsIsuYn; //ATS 거래종목 여부
scwin.gMktclsYn = $c.frame.path("../frame_head").scwin.gMktclsYn; //장종료 여부(18:00~20:00)
scwin.gAtsTrnsmYn = $c.frame.path("../frame_head").scwin.gAtsTrnsmYn; //거래정지 해당여부(ATS 전송여부)
scwin.gAtsTrnsmRsltCd = $c.frame.path("../frame_head").scwin.gAtsTrnsmRsltCd; //ATS 전송 결과(S_성공,E_실패,E1_실패(공시뷰어를 닫지 않은 경우))
scwin.gBatchReservYn = $c.frame.path("../frame_head").scwin.gBatchReservYn; //예약공시 여부(Y^20시이전,N^20시이후,^대상X)
scwin.gMsgSum = "";
scwin.vScrenID = 'ULDSTF10008.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_showOptButton = function() {
    if (scwin.gSndlocTp == '90') {
        // 지주회사연계공시
        img_hold.src = "../img/btn_hold_d.gif";
        img_hold.setDisabled(true);
    }

    // 2. 우편함 공시일때
    //alert("gHdcomLnkDisclsYn:"+gHdcomLnkDisclsYn+","+gSubcomDisclsProcsStatCd+","+ gSubcomNxtddTddTpCd);
    if (scwin.gNxtTpCd == 2 || scwin.gNxtTpCd == 4) {
        // 당일 또는 익일처리일때				
        $c.stf.showObj(pnl_today, false);
    } else if (scwin.gNxtTpCd == 1) {
        // 익일 -> 우편함으로 들어온경우		
        if (scwin.gDoc_LdMktTp == 2) {
            // 코스닥일때					
            $c.stf.showObj(pnl_today, true);
        } else if (scwin.gDoc_LdMktTp == 1) {
            // 유가일때
            if (scwin.gSndlocTp == '90' && scwin.gSubcomNxtddTddTpCd == '3') {
                // 지주회사연계공시이고 자회사공시를 익일공시-> 당일로 처리일때
                $c.stf.showObj(pnl_today, true);
            } else {
                $c.stf.showObj(pnl_today, false);
            }
        } else {
            $c.stf.showObj(pnl_today, false);
        }
    }
    if (scwin.gLangTpCd == '0') {
        // 국문일때, 첨부추가 및 첨부정정은 디폴트로 비전송으로 셋팅 :2008.06.27
        if (scwin.gDisclsAcptTpCd == 'A' || scwin.gDisclsAcptTpCd == 'U') {
            $c.stf.setObjectValue(rdo_trnsmtp, '2');
        }
    } else if (scwin.gLangTpCd == '1') {
        if (scwin.gSubmitSysTp == '0') {
            // 국문일때	
            // 영문일때, 무조건 디폴트로 비전송으로 셋팅:2008.06.27
            $c.stf.setObjectValue(rdo_trnsmtp, '2');
        } else if (scwin.gSubmitSysTp == '1') {
            // 영문제출이면서 첨부관련일때만 비전송
            if (scwin.gDisclsAcptTpCd == 'A' || scwin.gDisclsAcptTpCd == 'U') {
                $c.stf.setObjectValue(rdo_trnsmtp, '2');
            }
        }
    }

    // 사유지정 버튼 
    if (js_market == '1') {
        //  유가일때				
        $c.stf.showObj(img_rsn, false);
    } else {
        $c.stf.showObj(img_rsn, true);
    }

    //ATS 전송여부 버튼
    if (scwin.gSndlocTp == '90') {
        // 지주회사연계공시의 경우 ATS전송대상에서 제외하도록
        scwin.gAtsIsuYn = 'N';
    }

    //if (gAtsIsuYn == 'Y' && gMktclsYn == 'Y' && (gBelngDepCd == '2600' || gBelngDepCd == '3400')) {  //ATS 거래종목 여부 & 장종료 여부(18:00~20:00) & 공시팀
    if (scwin.gAtsIsuYn == 'Y' && scwin.gMktclsYn == 'Y') {
        //ATS 거래종목 여부 & 장종료 여부(18:00~20:00)
        panel_ATS.style.visibility = "";

        //ATS 전송여부 빈칸인 경우 검토/승인 버튼 비활성화
        if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) == '') {
            scwin.fn_DisableObj("study");
        }
    } else {
        panel_ATS.style.visibility = "hidden";
    }
};
scwin.fn_EnableObj = function(name) {
    var obj = eval("img_" + name);
    obj.src = "../img/btn_" + name + ".gif";
    obj.setDisabled(false);
};
scwin.fn_DisableObj = function(name) {
    var obj = eval("img_" + name);
    obj.src = "../img/btn_" + name + "_d.gif";
    obj.setDisabled(true);
};


// 로그인 사용자정보로 공시처리가능여부 체크 
scwin.fn_getProcButtonYN = function() {
    var url = "/Viewer.do?method=getProcBtnShowYn" + "&inputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&outputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&ACPT_NO=" + scwin.gAcptNo + "&DUTY_GRP_TP=" + scwin.gDutyGrp + "&DEP_CD=" + scwin.gDepCd;
    dts_btnshow.DataID = encodeURI(url);
    dts_btnshow.reset();
};


// 처리버튼 생성여부 
scwin.fn_showProcButton = function(pDutyProcYn, pGrnlProcYn, pCloseYn) {
    /*	
    alert(gDutyYn+","+pDutyProcYn+","+pGrnlProcYn+","+pCloseYn);	
    alert("gAcptNo-->"+gAcptNo);
    alert("pCloseYn-->"+pCloseYn);
    alert("gDutyYn-->"+gDutyYn);
    alert("gJobTitle-->"+gJobTitle);
    alert("pGrnlProcYn-->"+pGrnlProcYn);
    alert("gDutyChrg-->"+gDutyChrg);
    */
    if (scwin.gAcptNo != '') {
        // 가져온접수번호가 있으면 처리함.
        // 마감전일때
        if (pCloseYn == 'N') {
            if (scwin.gFormWarnContn != "") {
                label_WARN_CONTN.childNodes[0].innerText = scwin.gFormWarnContn;
            }

            // 로그한 사용자가 당번이면서 접수문서가 당번그룹에 해당할 경우
            if (scwin.gJobTitle == '40') {
                //부서장권한 제거 2013.03.26
                $c.stf.showObj(panel_1, false);
            } else {
                if ((scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') && pDutyProcYn == 'Y') {
                    // 패널라운드 처리	
                    $c.cm.PanelToGroupBox(panel_12);
                    $c.stf.showObj(panel_1, true);
                } else {
                    // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
                    //if (gJobTitle == '09' || gJobTitle == '40') {
                    if (scwin.gJobTitle == '09') {
                        //부서장권한 제거 2013.03.26
                        // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.(팀장은 담당종목팀만 처리가능으로 변경 2013.03.26)
                        $c.libRoundPanel.PanelToGroupBox(panel_12); // 패널라운드 처리	
                        $c.stf.showObj(panel_1, true);
                    } else {
                        // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                        if (pGrnlProcYn == 'Y') {
                            $c.cm.PanelToGroupBox(panel_12); // 패널라운드 처리	
                            $c.stf.showObj(panel_1, true);
                        } else {
                            $c.stf.showObj(panel_1, false);
                        }
                    }
                }
            }
        } else {
            // 마감후일때
            $c.stf.showObj(panel_1, false);
        }
    }
};




// 검토처리하기 
scwin.fn_DsclStudy = function() {
    // 전송구분 셋팅
    var vTrnsmtp = $c.stf.getObjectValue(rdo_trnsmtp);
    //alert(vTrnsmtp +"="+gAcptNo);
    if (scwin.gAcptNo == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    dts_AcptProcs.insertRow();
    dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_AcptProcs.setCellData(1, "TRNSM_TP_CD", vTrnsmtp);
    dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    if (scwin.gNxtTpCd == 2) {
        // 당일일때	
        dts_AcptProcs.setCellData(1, "NXTDD_TDD_TP", "2");
        vMethod = "processDisclosureStudy";
    } else {
        // 전체가 체크일때 
        if (chb_today.checked == true) {
            // 우편함 익익을 당일로
            dts_AcptProcs.setCellData(1, "NXTDD_TDD_TP", "3");
            vMethod = "processDisclosureStudyNxt";
        } else {
            // 우편함이므로 1로 셋팅	
            dts_AcptProcs.setCellData(1, "NXTDD_TDD_TP", "1");
            vMethod = "processDisclosureStudy";
        }
    }
    if (dts_AcptProcs.getCellData(1, "ACPT_NO") == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    var gShowloadYn = $c.frame.path("../frame_head").gShowloadYn;
    //alert('[gShowloadYn]'+gShowloadYn);

    if (gShowloadYn != 'Y') {
        $c.win.alert('문서 변환중이오니  변환완료후에 처리하시기 바랍니다.');
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) == 'Y') {
        //ATS 전송여부가 전송일 때 해당 컬럼 저장
        dts_AcptProcs.setCellData(1, "ATS_TRNSM_YN", $c.stf.getObjectValue(cmb_ATS_TRNSM_YN));
    }

    //ATS 전송 체크
    if (scwin.fn_CheckATS()) {
        var sMsg = "";
        if (scwin.gBatchReservYn == 'Y') {
            //20시 이전 예약공시
            sMsg = '20시 이후에 배포됩니다.(예약공시)\n';
        } else if (scwin.gBatchReservYn == 'N') {
            //20시 이후 예약공시
            sMsg = '즉시 배포됩니다.\n';
        }
        sMsg += '검토처리 하시겠습니까?';
        if (confirm(sMsg)) {
            if (scwin.fn_getProcsSate(scwin.gAcptNo) == false) {
                scwin.fn_CloseParentReload();
                return false;
            } else {
                trs_AcptProcs.Action = "/DisclosureStudy.do?method=" + vMethod + "&inputMessageId=DSCLPROC_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo;
                trs_AcptProcs.KeyName = "toinb_dataid4";
                trs_AcptProcs.KeyValue = "JSP(I:pInput=dts_AcptProcs)";
                trs_AcptProcs.Post();
            }
        }
    }
};





//ATS 전송 체크
scwin.fn_CheckATS = function() {
    //담당자 검토와 거래정지 해당여부 일치 확인
    if (scwin.gAtsIsuYn == 'Y' && scwin.gMktclsYn == 'Y') {
        //ATS 거래종목 여부 & 장종료 여부(18:00~20:00)
        //ATS 전송여부 저장에 사용
        dts_AcptProcs.setCellData(1, "ATS_TRNSM_YN", $c.stf.getObjectValue(cmb_ATS_TRNSM_YN));
        if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) == 'Y') {
            //ATS 전송여부가 전송일 때
            if (confirm("거래정지 해당을 선택하여 ATS 전문 전송 예정입니다.")) {
                //if(ex_confirm(1)) {	//거래정지 해당을 선택하여 ATS 전문 전송 예정입니다.
                return true;
            } else {
                return false;
            }
        } else if ($c.stf.getObjectValue(cmb_ATS_TRNSM_YN) == 'N') {
            if (confirm("거래정지 미해당을 선택하여 ATS 전문 미전송 예정입니다.")) {
                //if(ex_confirm(2)) {	//거래정지 미해당을 선택하여 ATS 전문 미전송 예정입니다.
                return true;
            } else {
                return false;
            }
        } else {
            $c.win.alert("거래정지 해당여부를 선택해 주세요.");
            return false;
        }
    }
    return true;
};
scwin.fn_GetMktclsYn = function() {
    var url = "/Viewer.do?method=getMktclsYn&ACPT_NO=" + scwin.gAcptNo + "&inputMessageId=VIEWER_OUT" + "&outputMessageId=VIEWER_OUT";
    dts_Mktcls.DataID = encodeURI(url);
    dts_Mktcls.reset();
};


// 처리상태 조회하기
scwin.fn_getProcsSate = function(gAcptNo) {
    var url = "/Viewer.do?method=getDsclProcsStat" + "&inputMessageId=VIEWER_OUT" + "&outputMessageId=VIEWER_OUT" + "&ACPT_NO=" + scwin.gAcptNo;
    dts_procs_stat.DataID = encodeURI(url);
    dts_procs_stat.reset();
    var vPROCS_STAT_CD = dts_procs_stat.getCellData(1, "PROCS_STAT_CD");
    var vPROCS_STAT_NM = dts_procs_stat.getCellData(1, "PROCS_STAT_NM");
    var vPROCS_DDTM = dts_procs_stat.getCellData(1, "PROCS_DDTM");
    var vBLOCK_YN = dts_procs_stat.getCellData(1, "BLOCK_YN");
    if (vBLOCK_YN == 'Y') {
        $c.win.alert(scwin.gTrdHaltMsg);
        return false;
    }
    if (scwin.gProcsStatCd != vPROCS_STAT_CD) {
        $c.win.alert("본 공시가 " + vPROCS_DDTM + "에  이미 [" + vPROCS_STAT_NM + "] 처리가 되었습니다.");
        //fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};




//  거래소제출문서 즉시 보류처리하기  
scwin.fn_DsclHold = function() {
    dts_ReservInfo.insertRow();
    dts_ReservInfo.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_ReservInfo.setCellData(1, "LDMKTTP_CD", scwin.gLdMktTpCd);
    dts_ReservInfo.setCellData(1, "RESERV_TP_CD", "1");
    dts_ReservInfo.setCellData(1, "DISCLS_RESERV_RSN_CD", "");
    dts_ReservInfo.setCellData(1, "DISCLS_PROCS_RSN_DTL_CONTN", "");
    dts_ReservInfo.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_ReservInfo.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    if (dts_ReservInfo.getCellData(1, "ACPT_NO") == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    var vAnswer = confirm('보류처리 하시겠습니까?');
    if (vAnswer == true) {
        if (scwin.fn_getProcsSate(scwin.gAcptNo) == false) {
            scwin.fn_CloseParentReload();
            return false;
        } else {
            trs_Reserv.Action = "/DisclosureStudy.do?method=processDisclosureHold&inputMessageId=RESERVRSN_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo;
            trs_Reserv.KeyName = "toinb_dataid4";
            trs_Reserv.KeyValue = "JSP(I:pInput=dts_ReservInfo)";
            trs_Reserv.Post();
        }
    }
};




// 처리중 처리하기
scwin.fn_DsclPreStudy = function() {
    if (scwin.gAcptNo == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    dts_AcptProcs.insertRow();
    dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    //dts_AcptProcs.NameValue(1,"TRNSM_TP_CD") = vTrnsmtp ;
    dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    if (dts_AcptProcs.getCellData(1, "ACPT_NO") == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    var vAnswer = confirm('처리중 상태로 처리하시겠습니까?');
    if (vAnswer == true) {
        if (scwin.fn_getProcsSate(scwin.gAcptNo) == false) {
            scwin.fn_CloseParentReload();
            return false;
        } else {
            trs_AcptProcs.Action = "/DisclosureStudy.do?method=processDisclosurePreStudy&inputMessageId=DSCLPROC_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo;
            trs_AcptProcs.KeyName = "toinb_dataid4";
            trs_AcptProcs.KeyValue = "JSP(I:pInput=dts_AcptProcs)";
            trs_AcptProcs.Post();
        }
    }
};





