    scwin.gAtsTrnsmRsltCd = dts_Mktcls.getCellData(1, "ATS_TRNSM_RSLT_CD");
    var mktclsYn = dts_Mktcls.getCellData(1, "MKTCLS_YN"); //장종료여부 확인
    var batchReservYn = dts_Mktcls.getCellData(1, "BATCH_RESERV_YN"); //예약공시여부 확인

    //alert("!" + gMktclsYn + "_" + mktclsYn + "_" + gAtsTrnsmRsltCd + "_\n_" + gBatchReservYn + "_" + batchReservYn);

    if (scwin.gMktclsYn != mktclsYn || scwin.gBatchReservYn != batchReservYn) {
        var vUrl = $c.frame.path("../").frame_head.srcUrl;
        $c.win.alert("장 중 여부가 변경되었습니다.\n검토 버튼을 다시 클릭해 주세요.");
        $c.frame.path("../").frame_head.srcUrl = vUrl;
